    [59569] = { 31717, 1, 128, "Bronze Drake", "Lost time is never found again. Oh, never mind I found it. -Chronormu", 0, "|cFFFFD200Drop: |rInfinite Corruptor|n|cFFFFD200Zone: |rThe Culling of Stratholme" },
    [59570] = { 31697, 1, 128, "Red Drake", "You should never listen to minstrels' fancies. A dragon would never hurt a soul, unless they tried to hurt him first.", 2, "|cFFFFD200Vendor: |rCielstrasza|n|cFFFFD200Zone: |rDragonblight|n|cFFFFD200Faction: |rThe Wyrmrest Accord - Exalted|n|cFFFFD200Cost: |r2000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
