    [59961] = { 31902, 1, 128, "Red Proto-Drake", "The vrykul were the first to recognize their potential. Or maybe the second, depending on how you look at it.", 5, "|cFFFFD200Achievement: |rGlory of the Hero|n|cFFFFD200Category: |rDungeons & Raids" },
    [59976] = { 31912, 1, 192, "Black Proto-Drake", "Bred specifically to honor those heroes who showed exceptional resilience and fortitude facing the dangers in Northrend.", 2, "|cFFFFD200Legacy|r" },
    [59996] = { 32151, 1, 128, "Blue Proto-Drake", "The Storm Peaks! There we will find the beast strong enough to bear me into battle. -Skadi the Ruthless", 0, "|cFFFFD200Drop: |rSkadi the Ruthless|n|cFFFFD200Zone: |rUtgarde Pinnacle" },
    [60002] = { 32153, 1, 128, "Time-Lost Proto-Drake", "The only reason for time is so that everything doesn't happen at once.", 0, "|cFFFFD200Drop: |rTime-Lost Proto-Drake|n|cFFFFD200Zone: |rThe Storm Peaks" },
    [60021] = { 32156, 1, 192, "Plagued Proto-Drake", "Bred specifically to honor those heroes who showed significant courage and persistence facing the dangers in Northrend.", 5, "|cFFFFD200Legacy|r" },
    [60024] = { 32157, 1, 128, "Violet Proto-Drake", "I cannot help but wonder if things would have turned out different if the titans had elevated even one more dragonflight. -Alexstrasza", 5, "|cFFFFD200Achievement: |rWhat a Long, Strange Trip It's Been|n|cFFFFD200Category: |rWorld Events" },
    [60025] = { 32158, 1, 128, "Albino Drake", "Even the Draconic Native Association tests proved inconclusive in determining if the albino drake is related to a known dragonflight. -Breanni", 5, "|cFFFFD200Achievement: |rLeading the Cavalry|n|cFFFFD200Category: |rGeneral" },
    [60114] = { 32206, 2, 4, "Armored Brown Bear", "This ursine mount's swiftness is enhanced by its heavy armor, imbued with magic from Kirin Tor magi.", 2, "|cFFFFD200Vendor: |rMei Francis|n|cFFFFD200Zone: |rDalaran|n|cFFFFD200Cost: |r750|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [60116] = { 32207, 2, 4, "Armored Brown Bear", "Your cries of \"For the Horde!\" will be much more menacing from atop a heavily armored bear that's barreling down on Alliance at top speed.", 2, "|cFFFFD200Vendor: |rMei Francis|n|cFFFFD200Zone: |rDalaran|n|cFFFFD200Cost: |r750|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [60118] = { 32203, 2, 4, "Black War Bear", "Killing leaders of the Horde is its own reward, but this intimidating beast is an excellent memento.", 5, "|cFFFFD200Achievement: |rFor The Alliance!|n|cFFFFD200Category: |rPlayer vs. Player" },
    [60119] = { 32205, 2, 4, "Black War Bear", "This formidable mount is bought with the blood of Alliance leaders, but you would have killed them for free.", 5, "|cFFFFD200Achievement: |rFor The Horde!|n|cFFFFD200Category: |rPlayer vs. Player" },
    [60120] = { 32208, 1, },
