    [61294] = { 32562, 1, 128, "Green Proto-Drake", "The vrykul were the first to recognize their potential. Or maybe the second, depending on how you look at it.", 0, "|cFFFFD200Drop:|r Cracked Egg" },
    [61309] = { 33030, 1, 1024, "Magnificent Flying Carpet", "Standard features include a sturdy imbued frostweave frame and real iceweb spider silk threading.  Spare head pillow sold separately.", 3, "|cFFFFD200Profession: |rTailoring" },
    [61425] = { 32633, 2, 4, "Traveler's Tundra Mammoth", "Ancient manuscripts depict merchants traveling across the frozen tundra with these colossal beasts, leading scholars to believe they are the first domesticated mounts.", 2, "|cFFFFD200Vendor: |rMei Francis|n|cFFFFD200Zone: |rDalaran|n|cFFFFD200Cost: |r20000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61442] = { 32634, 1, },
    [61444] = { 32635, 1, },
    [61446] = { 32636, 1, },
    [61447] = { 32640, 2, 4, "Traveler's Tundra Mammoth", "Riders and merchants alike trust only this strong and steadfast mammoth to carry them safely across the frigid tundra.", 2, "|cFFFFD200Vendor: |rMei Francis|n|cFFFFD200Zone: |rDalaran|n|cFFFFD200Cost: |r20000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61451] = { 33029, 1, 1024, "Flying Carpet", "Hop aboard this flying carpet to see the shining, shimmering, and splendid world of Azeroth, wonder by wonder.", 3, "|cFFFFD200Profession: |rTailoring" },
    [61465] = { 31862, 2, 4, "Grand Black War Mammoth", "Once used by giants to carry heavily armored warriors, these grand war mammoths can easily bear more than one rider of less-than-giant stature.", 0, "|cFFFFD200Drop: |rBoss Drop|n|cFFFFD200Location: |rVault of Archavon" },
    [61467] = { 31861, 2, 4, "Grand Black War Mammoth", "Rarely, a war mammoth is born stronger and more tractable than its peers. These mammoths are dubbed \"grand\" and carry more than one rider to the front lines.", 0, "|cFFFFD200Drop: |rBoss Drop|n|cFFFFD200Location: |rVault of Archavon" },
    [61469] = { 31857, 2, 4, "Grand Ice Mammoth", "At home on the narrow, icy trails of the Storm Peaks, these mammoths are the only mounts the ice giants trust to carry large loads and multiple riders.", 2, "|cFFFFD200Vendor: |rLillehoff|n|cFFFFD200Zone: |rThe Storm Peaks|n|cFFFFD200Faction: |rThe Sons of Hodir - Exalted|n|cFFFFD200Cost: |r10000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61470] = { 31858, 2, 4, "Grand Ice Mammoth", "Due to high winds and avalanches, the Sons of Hodir recommend bringing at least two companions if venturing into the dangerous Storm Peaks.", 2, "|cFFFFD200Vendor: |rLillehoff|n|cFFFFD200Zone: |rThe Storm Peaks|n|cFFFFD200Faction: |rThe Sons of Hodir - Exalted|n|cFFFFD200Cost: |r10000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61983] = { 32931, 0, },
    [61996] = { 31239, 1, 132, "Blue Dragonhawk", "Dragonhawks are among the deadliest known predators. They are able to spot prey from great distances, rush in, and rend with both talon and beak.", 5, "|cFFFFD200Achievement: |rMountain o' Mounts|n|cFFFFD200Category: |rGeneral" },
    [61997] = { 32944, 1, 132, "Red Dragonhawk", "Dragonhawks are among the deadliest known predators. They are able to spot prey from great distances, rush in, and rend with both talon and beak.", 5, "|cFFFFD200Achievement: |rMountain o' Mounts|n|cFFFFD200Category: |rGeneral" },
    [62048] = { 25064, 1, 192, "Illidari Doomhawk", "Once a year, a rift in time appears, and strange things occur. The Illidari scouts and Doomwalker were quite surprised to find themselves in Tanaris.", 0, "|cFFFFD200Drop: |rDoomwalker|n|cFFFFD200Zone: |rTanaris" },
    [63232] = { 33297, 2, 0, "Stormwind Steed", "Although raised in Stormwind, this breed showed unusual aptitude for the cold weather in Icecrown.", 2, "|cFFFFD200Vendor: |rCorporal Arthur Flew|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63635] = { 33299, 2, 0, "Darkspear Raptor", "This raptor breed was originally cultivated by the Drakkari, but has since been adopted by the Darkspear tribe in Northrend.", 2, "|cFFFFD200Vendor: |rSamamba|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63636] = { 33408, 2, 0, "Ironforge Ram", "Wildhammer Fact Checker claims that this specific breed was the first type of ram domesticated by the dwarves when they settled in Dun Morogh.", 2, "|cFFFFD200Vendor: |rDerrick Brindlebeard|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63637] = { 33298, 2, 0, "Darnassian Nightsaber", "When a night elf's mount perishes, it is custom for the rider to keep one of the saber's great fangs as a token of remembrance.", 2, "|cFFFFD200Vendor: |rRook Hawkfist|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63638] = { 33301, 2, 0, "Gnomeregan Mechanostrider", "When you absolutely, positively have to be there right now. -Rillie Spindlenut", 2, "|cFFFFD200Vendor: |rRillie Spindlenut|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63639] = { 33416, 2, 0, "Exodar Elekk", "Exodar Elekk are elekk which have been anointed by O'ros, the Naaru who journeyed from Draenor to Azeroth with Velen and his followers.", 2, "|cFFFFD200Vendor: |rIrisee|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63640] = { 33409, 2, 0, "Orgrimmar Wolf", "For a brief time, many orcs would declare themselves \"hungry like an Orgrimmar wolf.\" Some blood elves still use the phrase ironically.", 2, "|cFFFFD200Vendor: |rFreka Bloodaxe|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
