    [63844] = { 33857, 1, 128, "Argent Hippogryph", "Argent Hippogryphs will partner with only the bravest and most battle-tested champions.", 2, "|cFFFFD200Vendor: |rFaction Quartermasters|n|cFFFFD200Location: |rArgent Tournament, Icecrown|n|cFFFFD200Cost: |r150|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|n" },
