NE.collections.PetData =
{
    [4055] = { 2671, 9, 2, nil, "A mechanical squirrel's logic center tells it to collect and store both nuts and bolts for the winter.", 3, "|cFFFFD200Profession: |rEngineering" },
    [10673] = { 7385, 7, 2, nil, "Donni Anthania plans to have a bombay buried with her when she dies. A wise adventurer can put its talents to much better use.", 2, "|cFFFFD200Vendor: |rDonni Anthania|n|cFFFFD200Zone: |rElwynn Forest|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10674] = { 7384, 7, 2, nil, "Donni Anthania invites these cats to her tea parties. But she doesn't serve their favorite drink: the tears of their enemies.", 2, "|cFFFFD200Vendor: |rDonni Anthania|n|cFFFFD200Zone: |rElwynn Forest|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10675] = { 7383, 7, 2, nil, "Old Alterac saying: 'A cat has nine lives, but needs only one.'", 0, "|cFFFFD200Drop: |rWorld Drop|n|cFFFFD200Zone: |rAlterac Mountains" },
    [10676] = { 7382, 7, 2, nil, "The last person who tried to housebreak this cat quickly learned that a soiled rug is better than a shredded everything-else.", 2, "|cFFFFD200Vendor: |rDonni Anthania|n|cFFFFD200Zone: |rElwynn Forest|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10677] = { 7380, 7, 2, nil, "Known for its blue eyes. Also considered a delicacy by giant murlocs.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r60|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10678] = { 7381, 7, 2, nil, "Sleeping is this cat's second favorite activity. The first is yawning.", 2, "|cFFFFD200Vendor: |rDonni Anthania|n|cFFFFD200Zone: |rElwynn Forest|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10679] = { 7386, 7, 2, nil, "'The queen had three kittens. The first gave her a juicy rat. The second, a tasty hare. And the white, her favorite, presented the head of her rival.'", 2, "|cFFFFD200Vendor: |rLil Timmy|n|cFFFFD200Zone: |rStormwind City|n|cFFFFD200Cost: |r60|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10680] = { 7390, 2, 2, nil, "Some say this clever bird can be taught to speak--but it's smart enough to keep its beak shut.", 2, "|cFFFFD200Vendor: |rNarkk|n|cFFFFD200Zone: |rStranglethorn Vale|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10682] = { 7391, 2, 2, nil, "The jungle trolls train these birds to mimic calls for help in order to lure unsuspecting travelers into traps.", 0, "|cFFFFD200Drop: |rWorld Drop|n|cFFFFD200Zone: |rStranglethorn Vale" },
    [10683] = { 7387, 2, 2, nil, "Favored pet of the Defias pirates, this colorful bird is handy for remembering passwords, grocery lists, and cracker recipes.", 0, "|cFFFFD200Drop: |rDefias Pirate|n|cFFFFD200Zone: |rThe Deadmines" },
    [10684] = { 7389, 2, 2, nil, "Favored pet of the goblins of Booty Bay, this colorful bird is renowned for its ability to count coins, tally budgets, and lie about contracts.", 2, "|cFFFFD200Vendor: |rNarkk|n|cFFFFD200Zone: |rStranglethorn Vale|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10685] = { 7394, 2, 2, nil, "It thinks you taste like chicken too.", 2, "|cFFFFD200Vendor: |rMagus Tirth|n|cFFFFD200Zone: |rThousand Needles|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10688] = { 7395, 4, 2, nil, "The cockroach is usually an impulse buy. Its owners have a hard time parting with it even after numerous attempts.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendor: |rJeremiah Payson|n|cFFFFD200Zone: |rUndercity|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10695] = { 7543, 1, 2, nil, "Hopes that someday it can grow up to destroy villages, just like mommy.", 0, "|cFFFFD200Drop: |rWhelplings|n|cFFFFD200Zone: |rDustwallow Marsh, Badlands" },
    [10696] = { 7547, 1, 2, nil, "Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic.", 0, "|cFFFFD200Drop: |rWorld Drop|n|cFFFFD200Zone: |rAzshara" },
    [10697] = { 7544, 1, 2, nil, "Hailing from the Wetlands, this young dragon is just learning how to hunt, breathe fire, and go on cute destructive rampages.", 0, "|cFFFFD200Drop: |rWorld Drop|n|cFFFFD200Zone: |rWetlands" },
    [10698] = { 7545, 1, 2, nil, "Once bred and raised by the green dragon Itharius, this unique breed of dragon has settled in the jungles of Feralas.", 0, "|cFFFFD200Drop: |rAdolescent Whelp, Dreaming Whelp|n|cFFFFD200Zone: |rSwamp of Sorrows" },
    [10703] = { 7550, 8, 2, nil, "Vendors at the Darkmoon Faire offer strange and exotic wonders. They also sell wood frogs.", 2, "|cFFFFD200Vendor: |rFlik|n|cFFFFD200Event: |rDarkmoon Faire|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10704] = { 7549, 8, 2, nil, "Known for their powerful legs and keen eyesight.", 2, "|cFFFFD200Vendor: |rFlik|n|cFFFFD200Event: |rDarkmoon Faire|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10706] = { 7555, 2, 2, nil, "This dark-feathered bird of prey is often seen as a harbinger of doom amongst the druids of Teldrassil.", 2, "|cFFFFD200Vendor: |rShylenai|n|cFFFFD200Zone: |rDarnassus|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10707] = { 7553, 2, 2, nil, "Night elf children are given an owl feather on their first birthday as a token of good luck.", 2, "|cFFFFD200Vendor: |rShylenai|n|cFFFFD200Zone: |rDarnassus|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10708] = { 7554, 2, 26, nil, "Winterspring's furbolg prize the brilliant white feathers of these majestic creatures for ritual purposes.", 11, "" },
    [10709] = { 14421, 4, 2, nil, "A complex system of burrows protects the prairie dog from its neighbors' massive hooves.", 2, "|cFFFFD200Vendor: |rHalpa|n|cFFFFD200Zone: |rThunder Bluff|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10711] = { 7560, 4, 2, nil, "If you go chasing snowshoe rabbits, you know you're going to fall.", 2, "|cFFFFD200Vendor: |rYarlyn Amberstill|n|cFFFFD200Zone: |rDun Morogh|n|cFFFFD200Cost: |r20|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10713] = { 7561, 7, 2, nil, "A favored companion of Kirin Tor magi, this reptile makes one wonder whether it's truly a snake or something else altogether.", 2, "|cFFFFD200Vendor: |rBreanni|n|cFFFFD200Zone: |rDalaran|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10714] = { 7565, 7, 2, nil, "Xan'tish fearlessly tracks, captures, and trains these noble snakes so they will aid their comrades in battle.", 2, "|cFFFFD200Vendor: |rXan'tish|n|cFFFFD200Zone: |rOrgrimmar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10716] = { 7562, 7, 2, nil, "The brown snake is native to Horde-controlled territories. It seems unremarkable until its victims are within range.", 2, "|cFFFFD200Vendor: |rXan'tish|n|cFFFFD200Zone: |rOrgrimmar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10717] = { 7567, 7, 2, nil, "The crimson snake is favored among the Darkspear trolls for not only its vicious nature, but also its steadfast loyalty.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendor: |rXan'tish|n|cFFFFD200Zone: |rOrgrimmar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [12243] = { 8376, 9, 18, nil, "Not to worry; the combat mechanisms and homing logic have been disabled on this unit, I think. --Oglethorpe Obnoticus", 1, "|cFFFFD200Quest:|r An OOX of Your Own|n|cFFFFD200Zone:|r Booty Bay|n" },
    [13548] = { 30379, 2, 18, nil, "Don't call this bird chicken unless you want egg on your face.", 1, "|cFFFFD200Quest: |rCLUCK!|n|cFFFFD200Zone: |rWestfall" },
    [15048] = { 9656, 9, 2, nil, "Possibly explosive, definitely adorable. Keep away from open flame.", 3, "|cFFFFD200Profession: |rEngineering" },
    [15049] = { 9657, 9, 2, nil, "This tiny peacekeeper security bot is often outfitted with the latest arcane nullifiers and crowd pummelers. Not for the environmentally minded.", 3, "|cFFFFD200Profession: |rEngineering" },
    [15067] = { 9662, 1, 2, nil, "These adorable critters love snuggling with their owners after a long day of brutal, bloody battle.", 0, "|cFFFFD200Drop: |rWorld Drop|n|cFFFFD200Zone: |rFeralas" },
    [15999] = { 10259, 7, 2050, nil, "Worgs are the favored companions of orcs and are fiercely loyal on the battlefield.", 1, "|cFFFFD200Quest: |rKibler's Exotic Pets|n|cFFFFD200Zone: |rLower Blackrock Spire" },
    [16450] = { 10598, 7, 2, nil, "Although born in the warm heights of Blackrock Spire, the smolderweb hatchling can survive most environments.", 1, "|cFFFFD200Quest: |rEn-Ay-Es-Tee-Why|n|cFFFFD200Zone: |rLower Blackrock Spire" },
    [17707] = { 11325, 7, 82, nil, "This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature.", 7, "|cFFFFD200Promotion:|r World of Warcraft Collector's Edition" },
    [17708] = { 11326, 5, 82, nil, "AND THE HEAVENS SHALL TREMBLE, AND MAN SHALL WEEP, AND THE END OF DAYS SHALL--wait, why are you so tall?", 7, "|cFFFFD200Promotion:|r World of Warcraft Collectors Edition" },
    [17709] = { 11327, 4, 82, nil, "A small, fierce member of the Zerg swarm, the zergling is not to be trifled with. Very dangerous in high numbers.", 7, "|cFFFFD200Promotion:|r World of Warcraft Collectors Edition" },
    [19772] = { 12419, 9, 2, nil, "Talented engineers have crafted an exact replica of a wood frog, at only ten times the cost of buying the real thing.", 3, "|cFFFFD200Profession: |rEngineering" },
    [23811] = { 14878, 8, 18, nil, "The legendary ale frog was believed to be extinct until the strange brews at the Darkmoon Faire brought them out of hiding.", 6, "|cFFFFD200World Event:|r Darkmoon Faire" },
    [24696] = { 15186, 0, 82, nil, "Appearances of this beloved and ultra-reclusive murloc are sure to draw a crowd.", 7, "|cFFFFD200Promotion:|r BlizzCon 2005" },
    [24988] = { 15358, 0, 16466, nil, "Lurky's charming disposition and lively antics are guaranteed to soothe frustration and lighten even the darkest moods.", 7, "|cFFFFD200Promotion:|r Burning Crusade Collector's Edition (EU only)|n" },
    [25162] = { 15429, 5, 2, nil, "Warning: Wear gloves and goggles while handling disgusting oozeling. DO NOT WASH. Will stain most armor.", 0, "|cFFFFD200Drop:|r World Drop|n|cFFFFD200Creature:|r Oozes and Slimes" },
    [26010] = { 15699, 9, 2, nil, "This clever toy is equipped with a secret switch to disable its 'tranquil' mode. Luckily, even the engineers who built it don't know how to find it.", 3, "|cFFFFD200Profession: |rEngineering" },
    [26045] = { 15710, 6, 2, nil, "He loves to dance and wave and play with you! He melts after Winter Veil, but don't worry; he'll be back again someday!", 6, "|cFFFFD200World Event:|r Feast of Winter Veil|n" },
    [26529] = { 15706, 4, 2, nil, "Would rather not spend any more time inside a wrapped holiday gift box.", 6, "|cFFFFD200World Event:|r Feast of Winter Veil" },
    [26533] = { 15698, 0, 2, nil, "These off-season allies work tirelessly to prepare for the Feast of Winter Veil, and would appreciate not being disturbed the rest of the year.", 6, "|cFFFFD200World Event:|r Feast of Winter Veil" },
    [26541] = { 15705, 0, 2, nil, "During the majestic Winter Veil celebration, these faithful companions spread joy throughout the land. The rest of the year, they are busy.", 6, "|cFFFFD200World Event:|r Feast of Winter Veil" },
    [27241] = { 16069, 0, 16466, nil, "Gurky is a born performer, though she remains elusive, making public appearances only on the rarest of occasions.", 7, "|cFFFFD200Promotion:|r EU Fansite Promotion|n" },
    [27570] = { 16085, 0, 2, nil, "The power of love can be a dangerous thing, especially when wielded by an airborne, ill-tempered goblin.", 6, "|cFFFFD200World Event:|r Love is in the Air|n|cFFFFD200Vendor: |rLovely Merchant|n|cFFFFD200Cost: |r40|TINTERFACE\\ICONS\\INV_ValentinesCard01:0|t|n" },
    [28505] = { 16456, 7, 16466, nil, "This cub shares many traits with its relatives, but it's in a league of its own with its singing ability.", 7, "|cFFFFD200Promotion:|r iCoke" },
    [28738] = { 16547, 8, 2, nil, "Slow and steady wins the race.", 6, "|cFFFFD200World Event:|r Children's Week" },
    [28739] = { 16548, 4, 2, nil, "Many assume 'Wiggles' refers to the motion of this pig's posterior. They discover the true meaning when they see their own entrails.", 6, "|cFFFFD200World Event:|r Children's Week" },
    [28740] = { 16549, 4, 2, nil, "A clever tactician, Whiskers will feign death to fool predators and bill collectors.", 6, "|cFFFFD200World Event:|r Children's Week" },
    [28871] = { 16701, 6, 2, nil, "This little piece of summer smells of warm evenings and lightning storms. If you look closely, you might be able to make out a face.", 6, "|cFFFFD200World Event:|r Midsummer Fire Festival|n|cFFFFD200Vendor: |rMidsummer Merchant|n|cFFFFD200Cost: |r350|TINTERFACE\\ICONS\\INV_SummerFest_FireFlower:0|t" },
    [30156] = { 17255, 2, 2, nil, "After a harpy incursion in Feralas, several hippogryph nesting grounds were attacked. Hundreds of hatchlings were orphaned, and they have been entrusted to the care of the druids on Sardor Isle.", 8, "|cFFFFD200Trading Card Game:|r Heroes of Azeroth" },
    [32298] = { 18381, 1, 82, nil, "Offspring of the nether drakes of Outland, this young dragon is still growing into its role as hunter, protector, and adorable terror of the skies.", 7, "|cFFFFD200Promotion:|r Burning Crusade Collector's Edition" },
    [33050] = { 18839, 8, 2, nil, "Only magical wishes make magical crawdads. If you wish for a fish, fish for a wish.", 3, "|cFFFFD200Fishing:|r Fishing (430)|n|cFFFFD200Zone:|r Terokkar Forest (Fishing Nodes)" },
    [35156] = { 20408, 5, 2, nil, "The ethereal Rashaad began breeding these enigmatic creatures after learning of their ability to feed on arcane energies.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r40|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35239] = { 20472, 4, 2, nil, "This bunny is the cutest thing its opponent will ever see. It'll also be the last.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35907] = { 21010, 2, 2, nil, "Delicate denizen of Azuremyst Isle, this magical insect has been rumored to possess healing abilities.", 2, "|cFFFFD200Vendor: |rSixx|n|cFFFFD200Zone: |rThe Exodar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [35909] = { 21009, 2, 2, nil, "A product of exposure to wild magical energies, this insect is the unexpectedly colorful result of Azerothian moth species being released into the eco-domes of the Netherstorm.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35910] = { 21008, 2, 2, nil, "Prefers flying during thunderstorms, which are common in Azuremyst Isle.", 2, "|cFFFFD200Vendor: |rSixx|n|cFFFFD200Zone: |rThe Exodar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [35911] = { 21018, 2, 2, nil, "Prefers flying during foggy nights, which are common in Azuremyst Isle.", 2, "|cFFFFD200Vendor: |rSixx|n|cFFFFD200Zone: |rThe Exodar|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36027] = { 21055, 1, 2, nil, "Once prized by dragonhawk breeders in Silvermoon. Stands out at night to predators, making it necessary to gain awareness at an early age.", 2, "|cFFFFD200Vendor: |rJilanne|n|cFFFFD200Zone: |rEversong Woods|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36028] = { 21064, 1, 2, nil, "Mortal enemies with silver dragonhawks; on pretty good terms with golden dragonhawks.", 2, "|cFFFFD200Vendor: |rJilanne|n|cFFFFD200Zone: |rEversong Woods|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36029] = { 21063, 1, 2, nil, "Ferocious species of dragonhawk, often seen diving down on prey from high in the sky.", 2, "|cFFFFD200Vendor: |rJilanne|n|cFFFFD200Zone: |rEversong Woods|n|cFFFFD200Cost: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36031] = { 21056, 1, 2, nil, "Raised by the few dealers still willing to trade in Netherstorm.", 2, "|cFFFFD200Vendor: |rDealer Rashaad|n|cFFFFD200Zone: |rNetherstorm|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [36034] = { 21076, 2, 2, nil, "Commonly used by sporelings as a light source as they navigate the waterways of Zangarmarsh, this luminescent insect helps them avoid the dangerous bogflare needlers.", 0, "|cFFFFD200Drop: |rBogflare Needler|n|cFFFFD200Zone: |rZangarmarsh" },
    [39181] = { 22445, 2, 18, nil, "The magical energies released during Skywing's transformation back into his true arakkoa form liberated this poor creature, a fledgling bird imprisoned by Luanga in order to power his fowl curse.", 1, "|cFFFFD200Quest:|r Skywing|n|cFFFFD200Zone:|r Terokkar Forest|n|n" },
    [39709] = { 22943, 4, 2, nil, "Many a drunken Brewfest goer has told the tale of this mysterious creature, but few remember that tale in the morning.", 6, "|cFFFFD200World Event:|r Brewfest" },
    [40405] = { 23198, 4, 16466, nil, "Lucky squeals when he's angry or when he's eating. Either way, you don't want to bother him.", 7, "|cFFFFD200Promotion:|r World Wide Invitational 2007|n" },
    [40549] = { 23234, 7, 2, nil, "Although loath to part with Bananas, Landro realized it would be safer if the pet was far from Booty Bay when his father, King Mukla, discovered he was missing.", 8, "|cFFFFD200Trading Card Game:|r Through the Dark Portal" },
    [40613] = { 23231, 5, 2, nil, "He's slightly evil but extremely narcoleptic. Keep him away from critters!", 6, "|cFFFFD200World Event:|r Children's Week" },
    [40614] = { 23258, 4, 2, nil, "The sin'dorei use hawkstriders as mounts, but this little one was deemed unfit after being diagnosed with numerous anxiety disorders.", 6, "|cFFFFD200World Event:|r Children's Week" },
    [40634] = { 23266, 4, 2, nil, "Domesticated elekks are trained as mounts by the draenei people. In the wild they are hunted for their ivory tusks.", 6, "|cFFFFD200World Event:|r Children's Week" },
    [40990] = { 23274, 4, 82, nil, "Stinker uses his aroma to repel predators and attract cats. He's much more successful with the former than the latter.", 5, "|cFFFFD200Achievement: |rShop Smart, Shop Pet...Smart|n|cFFFFD200Category: |rGeneral" },
    [42609] = { 23909, 6, 2, nil, "This mischievous gourd likes to pop out of the ground and scare you right out of your pants. Hail to the pumpkin song!", 6, "|cFFFFD200World Event:|r Hallow's End" },
    [43697] = { 24388, 8, 2, nil, "The crocolisk's hide and meat are prized by hunters, but the beast is ferocious and seldom taken by surprise.", 3, "|cFFFFD200Profession: |rFishing|n|cFFFFD200Zone: |rShattrath" },
    [43698] = { 24389, 8, 2, nil, "Muckbreath is just like other crocolisks, except he has an excellent sense of humor.", 3, "|cFFFFD200Profession:|r Fishing|n|cFFFFD200Zone:|r Shattrath" },
    [43918] = { 24480, 8, 2, nil, "Amani witch doctors have turned many victims into frogs. Some never recover.", 0, "|cFFFFD200Drop:|r Forest Frog|n|cFFFFD200Zone:|r Zul'Aman" },
    [44369] = { 24753, 4, 2, nil, "A shy creature, the pink elekk will only make its presence known to those that have befriended it, or to anyone too intoxicated to harm it.", 6, "|cFFFFD200World Event:|r Brewfest|n|cFFFFD200Vendor: |rBelbi Quikswitch|n|cFFFFD200Zone: |rDun Morogh|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\INV_Misc_Coin_01:0|t|n|n|cFFFFD200Vendor: |rBliz Fixwidget|n|cFFFFD200Zone: |rDurotar|n|cFFFFD200Cost: |r100|TINTERFACE\\ICONS\\INV_Misc_Coin_01:0|t" },
    [45082] = { 25062, 2, 2, nil, "Wild sporebats are vicious creatures, but if tamed at a young age, they can be loyal companions.", 2, "|cFFFFD200Vendor: |rMycah|n|cFFFFD200Zone: |rZangarmarsh|n|cFFFFD200Faction: |rSporeggar - Exalted|n|cFFFFD200Cost: |r30|TINTERFACE\\ICONS\\INV_Mushroom_02:0|t" },
    [45125] = { 25109, 9, 2, nil, "When the Burning Legion invaded Outland, Landro Longshot contributed this design to the war effort. Both the Alliance and Horde passed on production.", 8, "|cFFFFD200Trading Card Game:|r March of the Legion" },
    [45127] = { 25110, 2, 2050, nil, "Much quieter than a real dragon.", 8, "|cFFFFD200Trading Card Game:|r March of the Legion" },
    [45174] = { 25146, 4, 82, nil, "This golden pig honors its ancestors by giving its allies good fortune.", 7, "|cFFFFD200Promotion:|r Recruit-A-Friend|n" },
    [45175] = { 25147, 4, 82, nil, "Druids think silver pigs have a special bond with golden pigs, as both breeds appeared on Azeroth at the same time.", 7, "|cFFFFD200Promotion:|r Recruit-A-Friend" },
    [45890] = { 25706, 6, 2, nil, "Elder shaman have warned that wisps of Ragnaros, loyal servants of the Firelord, have taken to the Molten Front.  Vigilance is advised.", 11, "" },
