-- ---------------------------------------------------------------------------
-- Lookup: kind is "MOUNT" or "CRITTER" (the GetNumCompanions/GetCompanionInfo filter names).
-- Returns name, lore, sourceText — any of which may be nil when the DB has no row for that spell.
-- ---------------------------------------------------------------------------
function NE.collections.GetInfo(kind, spellID)
  if not spellID then return nil end
  local t = (kind == "CRITTER") and NE.collections.PetData or NE.collections.MountData
  local row = t and t[spellID]
  if not row then return nil end
  return row[4], row[5], row[7]
end

-- Mount type/flags bitfields (row[2]/row[3]) — EZCollections' non-blizzlike encoding, used for the
-- type filter (Ground/Flying/Aquatic) and for the location-aware "usable right now" test:
--   type  0x1 = flying-only   0x2 = can go underwater (aquatic)   0x4 = scripted ground/flying hybrid
--   flags 0x2 = self-mount    (others unused here)
-- Returns type, flags (both default 0 when the mount has no data row).
function NE.collections.GetMountType(spellID)
  if not spellID then return 0, 0 end
  local row = NE.collections.MountData and NE.collections.MountData[spellID]
  if not row then return 0, 0 end
  return row[2] or 0, row[3] or 0
end

-- ---------------------------------------------------------------------------
-- Faction-specific mounts (ported from EZCollections Data/Mounts.lua Set(8,...)): the racial mounts
-- that show a Horde/Alliance crest watermark on their list row. 0 = Horde, 1 = Alliance.
-- ---------------------------------------------------------------------------
NE.collections.MountFaction = {}
do
  local horde    = { 61447, 68188, 16081, 64658, 22722, 22721, 22724, 16084, 18990, 61230, 60119, 64659, 18989, 61467, 65639, 65645, 68056, 17465, 23251, 59788, 59793, 66846, 6654, 8395, 23509, 32243, 32246, 63641, 63643, 6653, 22718, 23243, 32245, 32297, 55531, 63640, 63642, 10796, 32244, 35020, 59797, 60116, 17450, 23250, 32296, 35027, 61469, 61997, 17463, 64977, 65641, 66091, 23241, 63635, 580, 17462, 18991, 23246, 32295, 35028, 65644, 18992, 23242, 23252, 33660, 35018, 35022, 66088, 23248, 23249, 34795, 64657, 65646, 10799, 16080, 17464, 23247, 35025 }
  local alliance = { 16055, 61425, 16056, 60424, 17229, 16083, 458, 32290, 23225, 61470, 68187, 59799, 61996, 6899, 10789, 32240, 59791, 66090, 6898, 8394, 32292, 61465, 65637, 6648, 63638, 470, 63232, 10793, 10873, 16082, 17459, 17460, 22723, 32235, 32239, 48027, 63637, 17454, 22720, 23222, 23239, 32242, 35711, 60114, 472, 10969, 23221, 23240, 23338, 35710, 35714, 66847, 68057, 6777, 17461, 23219, 23227, 32289, 59785, 15779, 22717, 23510, 61229, 63636, 63639, 65638, 65640, 17453, 22719, 23223, 23229, 23238, 34406, 35712, 35713, 65642, 65643, 66087, 23228, 60118 }
  for _, id in ipairs(horde)    do NE.collections.MountFaction[id] = 0 end
  for _, id in ipairs(alliance) do NE.collections.MountFaction[id] = 1 end
end
function NE.collections.GetFaction(spellID)
  return spellID and NE.collections.MountFaction[spellID] or nil
end

-- ---------------------------------------------------------------------------
-- Source-type labels + accessor. The data row[6] is a 0-based source type; EZCollections' journal
-- maps it to BATTLE_PET_SOURCE_[type+1] (nil -> 12 "Other"). Those FrameXML strings don't exist on
-- 3.3.5a, so ship our own copy (used with a _G fallback for localized clients).
-- ---------------------------------------------------------------------------
NE.collections.SourceLabels = {
  [1] = "Drop", [2] = "Quest", [3] = "Vendor", [4] = "Profession", [5] = "Pet Battle",
  [6] = "Achievement", [7] = "World Event", [8] = "Promotion", [9] = "Trading Card Game",
  [10] = "In-Game Shop", [11] = "Discovery", [12] = "Other",
}
function NE.collections.SourceLabel(idx)
  return (idx and _G["BATTLE_PET_SOURCE_" .. idx]) or NE.collections.SourceLabels[idx] or "Other"
end
-- Returns the 1-based source index for a companion (mounts + pets), matching SourceLabels.
function NE.collections.GetSourceIndex(kind, spellID)
  if not spellID then return 12 end
  local t = (kind == "CRITTER") and NE.collections.PetData or NE.collections.MountData
  local row = t and t[spellID]
  local st = row and row[6]
  return (st ~= nil) and (st + 1) or 12
end
